package com.lumoren.agentchat.ui.theme;

import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.resources.ResourceLocation;

/**
 * Constants and blit helpers for the original mechanical UI sprites
 * (generated by {@code tools/sprites/generate_sprites.py}; no Create mod
 * assets are used).
 * <p>
 * Panels are 24x24 with 8 px bands drawn as axis-uniform bands, so the
 * manual nine-slice below keeps every edge line pixel-crisp.
 */
public final class MechanicalSprites {

    private static final String STYLE = "textures/gui/create_style/";
    private static final String ICONS = "textures/gui/sprites/";

    public static final ResourceLocation PANEL_IRON = style("panel_iron");
    public static final ResourceLocation PANEL_INSET = style("panel_inset");
    public static final ResourceLocation FRAME_BRASS = style("frame_brass");
    public static final ResourceLocation BUTTON_BRASS = style("button_brass");
    public static final ResourceLocation BUTTON_COPPER = style("button_copper");
    public static final ResourceLocation BUTTON_DANGER = style("button_danger");
    public static final ResourceLocation TAB_SEGMENT = style("tab_segment");
    public static final ResourceLocation SCROLLBAR = style("scrollbar");
    public static final ResourceLocation RIVET = style("rivet");

    public static final ResourceLocation ICON_SEND = icon("send");
    public static final ResourceLocation ICON_SEND_DARK = icon("send_dark");
    public static final ResourceLocation ICON_PLUS = icon("plus");
    public static final ResourceLocation ICON_SETTINGS = icon("settings");
    public static final ResourceLocation ICON_TRASH = icon("trash");
    public static final ResourceLocation ICON_CHEVRON_LEFT = icon("chevron_left");
    public static final ResourceLocation ICON_CHEVRON_RIGHT = icon("chevron_right");
    public static final ResourceLocation ICON_COPY = icon("copy");
    public static final ResourceLocation ICON_EDIT = icon("edit");
    public static final ResourceLocation ICON_RECALL = icon("recall");
    public static final ResourceLocation ICON_RECIPE = icon("recipe");
    public static final ResourceLocation ICON_USAGE = icon("usage");
    public static final ResourceLocation ICON_TASK = icon("task");
    public static final ResourceLocation ICON_SOURCE = icon("source");
    public static final ResourceLocation ICON_WARNING = icon("warning");
    public static final ResourceLocation ICON_CLOSE = icon("close");
    public static final ResourceLocation ICON_HISTORY = icon("history");

    public static final ResourceLocation[] SPINNER_GEARS = {
            icon("spinner_gear_0"), icon("spinner_gear_1"),
            icon("spinner_gear_2"), icon("spinner_gear_3")
    };

    /** All sprite locations, for existence tests. */
    public static final ResourceLocation[] ALL = {
            PANEL_IRON, PANEL_INSET, FRAME_BRASS, BUTTON_BRASS, BUTTON_COPPER,
            BUTTON_DANGER, TAB_SEGMENT, SCROLLBAR, RIVET,
            ICON_SEND, ICON_SEND_DARK, ICON_PLUS, ICON_SETTINGS, ICON_TRASH,
            ICON_CHEVRON_LEFT, ICON_CHEVRON_RIGHT, ICON_COPY, ICON_EDIT, ICON_RECALL,
            ICON_RECIPE, ICON_USAGE, ICON_TASK, ICON_SOURCE, ICON_WARNING,
            ICON_CLOSE, ICON_HISTORY,
            SPINNER_GEARS[0], SPINNER_GEARS[1], SPINNER_GEARS[2], SPINNER_GEARS[3]
    };

    private MechanicalSprites() {
    }

    private static ResourceLocation style(String name) {
        return ResourceLocation.fromNamespaceAndPath("agentchat", STYLE + name + ".png");
    }

    private static ResourceLocation icon(String name) {
        return ResourceLocation.fromNamespaceAndPath("agentchat", ICONS + name + ".png");
    }

    /**
     * Draws a nine-slice panel: corners native, edges/center stretched.
     * Safe for textures whose bands are uniform along the stretch axis.
     *
     * @param border slice border in px (8 for 24x24 panels, 4 for the 8x24 scrollbar)
     */
    public static void blitNineSlice(GuiGraphics g, ResourceLocation texture,
                                     int x, int y, int width, int height,
                                     int textureWidth, int textureHeight, int border) {
        int centerW = Math.max(0, width - border * 2);
        int centerH = Math.max(0, height - border * 2);
        int srcCenterW = textureWidth - border * 2;
        int srcCenterH = textureHeight - border * 2;

        // corners
        g.blit(texture, x, y, 0, 0, border, border, textureWidth, textureHeight);
        g.blit(texture, x + width - border, y, textureWidth - border, 0, border, border, textureWidth, textureHeight);
        g.blit(texture, x, y + height - border, 0, textureHeight - border, border, border, textureWidth, textureHeight);
        g.blit(texture, x + width - border, y + height - border,
                textureWidth - border, textureHeight - border, border, border, textureWidth, textureHeight);
        // edges (stretched along one axis; bands are uniform on that axis)
        if (centerW > 0) {
            g.blit(texture, x + border, y, border, 0, centerW, border, textureWidth, textureHeight);
            g.blit(texture, x + border, y + height - border,
                    border, textureHeight - border, centerW, border, textureWidth, textureHeight);
        }
        if (centerH > 0) {
            g.blit(texture, x, y + border, 0, border, border, centerH, textureWidth, textureHeight);
            g.blit(texture, x + width - border, y + border,
                    textureWidth - border, border, border, centerH, textureWidth, textureHeight);
        }
        // center
        if (centerW > 0 && centerH > 0 && srcCenterW > 0 && srcCenterH > 0) {
            g.blit(texture, x + border, y + border, border, border, centerW, centerH, textureWidth, textureHeight);
        }
    }

    /** Draws a 24x24 panel (8 px border). */
    public static void blitPanel(GuiGraphics g, ResourceLocation texture,
                                 int x, int y, int width, int height) {
        blitNineSlice(g, texture, x, y, width, height, 24, 24, 8);
    }

    /** Draws the 8x24 scrollbar thumb (4 px border). */
    public static void blitScrollbarThumb(GuiGraphics g, int x, int y, int height) {
        blitNineSlice(g, SCROLLBAR, x, y, 8, height, 8, 24, 4);
    }

    /** Draws a 12x12 icon. */
    public static void blitIcon(GuiGraphics g, ResourceLocation icon, int x, int y) {
        g.blit(icon, x, y, 0, 0, GuideTheme.ICON_SIZE, GuideTheme.ICON_SIZE,
                GuideTheme.ICON_SIZE, GuideTheme.ICON_SIZE);
    }

    /** Draws the rivet at a panel corner. */
    public static void blitRivet(GuiGraphics g, int x, int y) {
        g.blit(RIVET, x, y, 0, 0, GuideTheme.RIVET_SIZE, GuideTheme.RIVET_SIZE,
                GuideTheme.RIVET_SIZE, GuideTheme.RIVET_SIZE);
    }

    /** Spinner gear frame for a 250 ms stepped animation. */
    public static ResourceLocation spinnerFrame(long millis) {
        return SPINNER_GEARS[(int) ((millis / 250) % SPINNER_GEARS.length)];
    }
}
